create or replace function public.current_company_id() returns uuid language sql stable security definer set search_path=public as $$select company_id from public.profiles where user_id=auth.uid() and status='active' limit 1$$;
create or replace function public.current_user_role() returns text language sql stable security definer set search_path=public as $$select role from public.profiles where user_id=auth.uid() and status='active' limit 1$$;
create or replace function public.bootstrap_company(p_company_name text,p_company_code text,p_slug text,p_user_id uuid,p_display_name text default null,p_timezone text default 'America/Monterrey') returns uuid language plpgsql security definer set search_path=public as $$declare c uuid;begin insert into public.companies(name,code,slug,timezone) values(p_company_name,p_company_code,lower(p_slug),p_timezone) returning id into c;insert into public.profiles(user_id,company_id,role,display_name,status) values(p_user_id,c,'company_admin',p_display_name,'active');insert into public.company_settings(company_id,default_timezone) values(c,p_timezone);return c;end$$;
